"use strict";(globalThis.webpackChunkgrc||=[]).push([[78934],{377(e){e.exports=JSON.parse('{"citeKey":"eswaradass2006networkbandwidth","slug":"eswaradass-2006-network-bandwidth-15a5","title":"Network Bandwidth Predictor (NBP): A System for Online Network Performance Forecasting","authors":["A. Eswaradass","X.-H. Sun","M. Wu"],"venue":"The 6th IEEE International Symposium on Cluster Computing and the Grid, Singapore","type":"Conference","entryType":"inproceedings","date":"May, 2006","year":2006,"era":"iit","month":5,"doi":"10.1109/ccgrid.2006.72","abstract":"The applicability of network-based computing depends on the availability of the underlying network bandwidth. However, network resources are shared and the available network bandwidth varies with time. There is no satisfactory solution available for network performance predictions. In this research, we propose, design, and implement the NBP (Network Bandwidth Predictor) for rapid network performance prediction. NBP is a new system that employs a neural network based approach for network bandwidth forecasting. This system is designed to integrate with most advanced technologies. It employs the NWS (Network Weather Service) monitoring subsystem to measure the network traffic, and provides an improved, more accurate performance prediction than that of NWS, especially with applications with a network usage pattern. The NBP system has been tested on real time data collected by NWS monitoring subsystem and on trace files. Experimental results confirm that NBP has an improved prediction.","hasAbstract":true,"lede":"In this research, we propose, design, and implement the NBP (Network Bandwidth Predictor) for rapid network performance prediction.","links":{"pdf":"https://grc.iit.edu/papers/2006/eswaradass-2006-network-bandwidth-15a5.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);